import{_ as n,a0 as d,w as l,s as p,I as s,x as i,a1 as a,A as o,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"4 个用于提高生产力的 Vim 功能 | LCTT x X-CMD","titleTemplate":false,"description":"4 个用于提高生产力的 Vim 功能 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 个用于提高生产力的 Vim 功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 个用于提高生产力的 Vim 功能 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220301 4 Vim features to use to improve productivity","title":"4 个用于提高生产力的 Vim 功能","tag":"202203","desc":""},"relativePath":"202203/20220301 4 Vim features to use to improve productivity.md","filePath":"[post].md"}'),m={name:"202203/20220301 4 Vim features to use to improve productivity.md"};function u(h,e,g,k,c,f){const t=d("Link");return l(),p("div",null,[e[22]||(e[22]=s("h1",{id:"_4-个用于提高生产力的-vim-功能",tabindex:"-1"},[i("4 个用于提高生产力的 Vim 功能 "),s("a",{class:"header-anchor",href:"#_4-个用于提高生产力的-vim-功能","aria-label":"Permalink to “4 个用于提高生产力的 Vim 功能”"},"​")],-1)),e[23]||(e[23]=s("blockquote",null,[s("p",null,"Vim 有很多技巧，即使是用过它很多年的人仍然可以学习新东西。")],-1)),e[24]||(e[24]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202203/04/102118tgy1i7albn6ndiri.jpg",alt:""})],-1)),s("p",null,[e[3]||(e[3]=i("Vim 总在那里。Vim 是当今最流行的文本编辑器之一。这在很大程度上是因为它随处可见。当你通过 SSH 连接到另一个系统时，你可能找不到 ",-1)),a(t,{href:"https://opensource.com/article/20/3/getting-started-emacs"},{default:o(()=>[...e[0]||(e[0]=[i("Emacs",-1)])]),_:1}),e[4]||(e[4]=i("、",-1)),a(t,{href:"https://opensource.com/article/20/12/gnu-nano"},{default:o(()=>[...e[1]||(e[1]=[i("Nano",-1)])]),_:1}),e[5]||(e[5]=i(" 或 ",-1)),a(t,{href:"https://opensource.com/article/20/6/open-source-alternatives-vs-code"},{default:o(()=>[...e[2]||(e[2]=[i("VSCodium",-1)])]),_:1}),e[6]||(e[6]=i("，但你可以放心，Vim 就在那里。",-1))]),e[25]||(e[25]=r('<p>在本文中，我介绍了一些你可以用 Vim 做的中级事情，以加快你的工作流程并通常让你的一天更轻松。本文假设你以前使用过 Vim，已经了解编辑器的基础知识，并希望将你的 Vim 技能提高一个档次。Vim 充满了有用的技巧，没有人真正掌握它，但本文中的五个技巧可以提高你的技能，并希望让你更加爱上最受欢迎和喜爱的文本编辑器之一。</p><h3 id="vim-书签" tabindex="-1">Vim 书签 <a class="header-anchor" href="#vim-书签" aria-label="Permalink to “Vim 书签”">​</a></h3><p>Vim 提供了一种在文本中添加书签的简单方法。假设你正在编辑一个大文件，并且当前的编辑会话要求你在文件中不同位置的两段文本之间来回跳转。</p><p>首先，你输入 <code>m</code>（用于标记）为当前位置设置一个书签，然后为其命名。例如，如果我正在编辑的文件中有一个名称列表，我想稍后再跳回，我可以使用 <code>mn</code>（n 表示名称）为文件的该部分添加书签。</p><p>稍后，在编辑文件的另一部分并希望跳回该名称列表时，我有两个选项。我可以输入 `<code>n</code>（反引号 n）转到书签的位置，或者我可以键入 <code>&#39;n</code>（单引号 n）转到书签所在行的开头。</p><p>当我不再需要书签时，我可以使用 <code>:delmarks n</code> 将其删除。<code>:marks</code> 会显示我所有的书签。</p><p>请注意，我使用小写字母来命名我的书签。这是故意的。你可以使用小写字母作为本地书签，使用大写字母来使书签在多个文件中具有全局性。</p><h3 id="vim-用户定义的缩写" tabindex="-1">Vim 用户定义的缩写 <a class="header-anchor" href="#vim-用户定义的缩写" aria-label="Permalink to “Vim 用户定义的缩写”">​</a></h3><p>如果你正在处理的文本有一个长词或短语多次出现，那么每次都完整地输入它会很快变得烦人。幸运的是，Vim 提供了一种创建缩写的简单方法。</p><p>要将 <code>Acme Painted Fake Roadways, Inc.</code> 的用户定义缩写设置为 <code>apfr</code>， 你需要输入 <code>:ab apfr Acme Painted Fake Roadways, Inc.</code>。现在当在编辑模式时，当你在输入 <code>apfr</code> 后面更上空格，就会变成 <code>Acme Painted Fake Roadways, Inc.</code>。</p><p>当你关闭 Vim 会话时，你使用 <code>:ab</code> 设置的任何缩写都会丢失。如果你想在此之前取消设置缩写，你可输入 <code>:una apfr</code>。</p><h3 id="vim-自动补全" tabindex="-1">Vim 自动补全 <a class="header-anchor" href="#vim-自动补全" aria-label="Permalink to “Vim 自动补全”">​</a></h3><p>许多人没有意识到 Vim 带有自动补全功能。如果你在文件中输入以前使用过的长词，这是一个方便的工具。</p><p>假设你正在撰写一篇文章，多次使用 <code>Antarctica</code> 一词。使用一次后，下次你可以只输入前几个字母。例如，你输入 <code>Ant</code> 然后按下 <code>Ctrl+P</code>。 Vim 要么补全单词（如果只有一个选项），要么为你提供可以用箭头键选择的单词列表，继续输入以进一步缩小搜索范围并使用 <code>Tab</code> 键选择单词。</p><h3 id="vim-范围选择" tabindex="-1">Vim 范围选择 <a class="header-anchor" href="#vim-范围选择" aria-label="Permalink to “Vim 范围选择”">​</a></h3><p>使用 Vim，你可以轻松地对文件中的一系列行执行操作。你可以通过起始行号、逗号和结束行号（包括）来指示范围。除了文字行号之外，你还可以使用句点（<code>.</code>）表示当前行，使用美元符号 （<code>$</code>） 表示文件缓冲区中的最后一行，以及使用百分号（<code>%</code>）表示整个文件。</p><p>这里举几个例子来说明。</p><p>如果要删除第 2 到 10 行，请输入（在命令模式下）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:2,10d</span></span></code></pre></div><p>要删除从第 25 行到文件末尾的每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:25,$d</span></span></code></pre></div><p>你可以使用以下命令删除每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:%d</span></span></code></pre></div><p>要将第 5 到 10 行复制（或转移）到第 15 行之后：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:5,10t 15</span></span></code></pre></div><p>要将第 5 行到第 10 行移动到第 15 行之后（而不是复制）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:5,10m 15</span></span></code></pre></div><h3 id="vim-提高生产力" tabindex="-1">Vim 提高生产力 <a class="header-anchor" href="#vim-提高生产力" aria-label="Permalink to “Vim 提高生产力”">​</a></h3><p>我希望这篇文章教会了你一些关于 Vim 文本编辑器的新知识。 Vim 有很多技巧，即使是使用了多年的人仍然可以学习新事物。总有一些新的和有用的东西可以学习。</p><hr>',30)),s("p",null,[e[8]||(e[8]=i("via: ",-1)),a(t,{href:"https://opensource.com/article/22/3/vim-features-productivity"},{default:o(()=>[...e[7]||(e[7]=[i("https://opensource.com/article/22/3/vim-features-productivity",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=i("作者：",-1)),a(t,{href:"https://opensource.com/users/hunterc"},{default:o(()=>[...e[9]||(e[9]=[i("Hunter Coleman",-1)])]),_:1}),e[14]||(e[14]=i(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[10]||(e[10]=[i("lujun9972",-1)])]),_:1}),e[15]||(e[15]=i(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:o(()=>[...e[11]||(e[11]=[i("geekpi",-1)])]),_:1}),e[16]||(e[16]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[12]||(e[12]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[17]||(e[17]=[i("LCTT",-1)])]),_:1}),e[20]||(e[20]=i(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:o(()=>[...e[18]||(e[18]=[i("Linux中国",-1)])]),_:1}),e[21]||(e[21]=i(" 荣誉推出",-1))])])}const C=n(m,[["render",u]]);export{v as __pageData,C as default};
